#!/usr/bin/env python3
"""Turn the vendored Lucide SVGs in icons/ into nodes.js (WEB-01).

The app inlines icons with `icon(name)` in webapp/icons.js, built with
createElementNS from the element lists this writes, so no SVG markup is ever
parsed from a string (CLAUDE.md: no innerHTML). Run after adding an SVG:

    python3 -I webapp/vendor/lucide/build.py          # writes nodes.js
    python3 -I webapp/vendor/lucide/build.py --check  # fails if nodes.js is stale

Standard library only. Lucide is ISC (LICENSE here); version in PROVENANCE.md.
"""
import json
import pathlib
import sys
import xml.etree.ElementTree as ET

HERE = pathlib.Path(__file__).resolve().parent
SVG = "{http://www.w3.org/2000/svg}"
KEEP = {"d", "cx", "cy", "r", "rx", "ry", "x", "y", "x1", "y1", "x2", "y2", "width", "height", "points"}


def nodes():
    out = {}
    for path in sorted((HERE / "icons").glob("*.svg")):
        root = ET.fromstring(path.read_text(encoding="utf8"))
        items = []
        for child in root:
            tag = child.tag.replace(SVG, "")
            if tag not in {"path", "circle", "rect", "line", "polyline", "polygon", "ellipse"}:
                sys.exit(f"{path.name}: unexpected element {tag}")
            items.append([tag, {k: v for k, v in child.attrib.items() if k in KEEP}])
        out[path.stem] = items
    return out


def render():
    body = json.dumps(nodes(), indent=None, separators=(",", ":"), sort_keys=True)
    return (
        "// Generated by webapp/vendor/lucide/build.py from the SVGs in icons/ "
        "(Lucide, ISC). Do not edit.\n"
        f"export const NODES = {body};\n"
    )


def main():
    target = HERE / "nodes.js"
    text = render()
    if "--check" in sys.argv:
        if not target.exists() or target.read_text(encoding="utf8") != text:
            sys.exit("webapp/vendor/lucide/nodes.js is stale: run python3 -I webapp/vendor/lucide/build.py")
        print("lucide nodes.js is current")
        return
    target.write_text(text, encoding="utf8")
    print(f"wrote {target.name}: {len(nodes())} icons")


if __name__ == "__main__":
    main()
